<script>
document.querySelector('form').addEventListener('submit', function () { const area=document.getElementById('requirements-lines'); const hidden=document.createElement('div'); area.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).forEach((value,index)=>{const input=document.createElement('input');input.type='hidden';input.name=`entry_requirements[${index}]`;input.value=value;hidden.appendChild(input)});this.appendChild(hidden);area.disabled=true; });
document.getElementById('add-intake').addEventListener('click', function(){const box=document.getElementById('intake-list');const i=box.children.length;if(i>=12)return;box.insertAdjacentHTML('beforeend',`<div class="row g-2 mb-2"><div class="col-md-3"><input class="form-control" name="intakes[${i}][label]" placeholder="Fall 2027"></div><div class="col-md-2"><input class="form-control" type="date" name="intakes[${i}][start_date]"></div><div class="col-md-2"><input class="form-control" type="date" name="intakes[${i}][application_deadline]"></div><div class="col-md-2"><select class="form-select" name="intakes[${i}][status]"><option value="open">Open</option><option value="closed">Closed</option></select></div><div class="col-md-3"><input class="form-control" type="url" name="intakes[${i}][source_url]" placeholder="Official source URL"></div></div>`)});
</script>
